INSERT INTO "game_tasks" ("id", "name", "descr", "npc", "map", "reward", "level_min", "level_max", "exp", "goal_item", "goal_qty", "repeatable") VALUES
  (1, '守卫的委托：消灭甲虫', '接受龙城守城卫兵阿蒙的委托，去听溪走廊、缘溪走廊或阳泉平原消灭甲虫，取回10个硬壳。', '守城卫兵阿蒙', '龙城', '5银币。', 10, 15, 10000, 4146, 10, TRUE),
  (100, '出云的狩猎（二）', '这次狩猎的目标是出云城外青牛山脚附近打败20只小猪神、雪女20个和玄武兽20个。', '祭庙守卫博文', '出云城', '18000点经验，5点名誉，18个银币', 25, 110, 10000, 0, 0, FALSE),
  (101, '出云的狩猎（三）', '清除幻萤谷附近的红鱼怪30只、金鱼怪30个。这样城里的情侣又能到那边约会了。', '祭庙守卫博文', '出云城', '22000点经验，5点名誉，22个银币', 27, 110, 10000, 0, 0, FALSE),
  (102, '出云的狩猎（四）', '偷吃食物和供品的妖物出没在青牛山、青牛山脚附近的飞天猪30只和小猪神20个。教训一下它们，让它们从此不敢偷吃。', '祭庙守卫博文', '出云城', '25000点经验，6点名誉，25个银币', 29, 110, 10000, 0, 0, FALSE),
  (103, '出云的狩猎（五）', '这次需要狩猎的妖物全部都在青牛山、大秦山、幻萤谷附近，今年的供品将会用到苍狼皇、碧磷毒蛇、金鱼怪、小猪神、飞天猪，每一种都是36只。', '祭庙守卫博文', '出云城', '70000点经验，10点名誉，32个银币，获得称号“出云极速猎手”', 31, 110, 10000, 0, 0, FALSE),
  (104, '紫气东来', '就请阁下在这函谷岭附近驱杀牛头面具36只，我再为你一一道来。', '祭庙守卫武藏', '出云城', '22000点经验，6点名誉，22个银币', 28, 110, 10000, 0, 0, FALSE),
  (105, '初探修罗殿', '先下这修罗殿1层附近驱杀跳跳尸七七四十九只，让我看看你的功夫。', '祭庙守卫武藏', '出云城', '25000点经验，6点名誉，25个银币', 32, 110, 10000, 0, 0, FALSE),
  (106, '利爪魔匙', '这魔匙有2种，一种是利爪铁匙，一种是利爪铜匙。在这修罗殿附近怪物身上掉落，你去给巡卫阿芥各找10根回来。', '巡卫阿芥', '出云城', '31000点经验，8点名誉，30个银币', 34, 110, 10000, 3651, 10, FALSE),
  (107, '左右为难', '到修罗殿3层附近驱杀双头鬼侍30只，这可是份苦差事。', '祭庙守卫武藏', '出云城', '40000点经验，7点名誉，40个银币', 36, 110, 10000, 0, 0, FALSE),
  (108, '安魂曲', '修罗殿附近驱杀双头鬼侍，有时会掉落夜灵珠。利爪鬼魂，有时会掉落暗灵珠。', '祭庙守卫武藏', '出云城', '25000点经验，7点名誉，40个银币', 36, 110, 10000, 4316, 10, FALSE),
  (109, '甜蜜蜜', '前天郊有很多QQ糖。身上会掉很多糖果，请给我收集甜蜜蜜30个吧。', '天兵扬海', '天都', '28000点经验，8点名誉，30个银币', 31, 110, 10000, 3653, 30, FALSE),
  (11, '老婆大人【之一】', '帮龙城守城卫兵阿炎准备送给老婆大人的生日礼物－－玫瑰花。', '守城卫兵阿炎', '龙城', '4500点经验值；5点名誉值；12银币。', 25, 40, 10000, 0, 0, FALSE),
  (110, '仙符', '这次的目标是天都附近的仙符40只。', '天兵沙空', '天都', '31000点经验，8点名誉，30个银币', 33, 110, 10000, 0, 0, FALSE),
  (111, '百足无僵', '请驱赶后天郊的蜈蚣风筝和仙符各36只，亏待不了你的。', '天兵沙空', '天都', '36000点经验，10点名誉，40个银币', 34, 110, 10000, 0, 0, FALSE),
  (112, '火鸟的报复', '你去引开一下火鸟30只，分散它们的注意力。', '天兵沙空', '天都', '40000点经验，8点名誉，45个银币', 36, 110, 10000, 0, 0, FALSE),
  (113, '四大精灵', '请你打败，蓬莱周围聚集的精灵，风精灵、火精灵、雪精灵、冰精灵，每一种都是20只。', '天兵扬海', '天都', '44000点经验，12点名誉，48个银币', 38, 110, 10000, 0, 0, FALSE),
  (114, 'QQ糖', '前天郊有很多QQ糖，请帮忙驱赶30只。', '天兵扬海', '天都', '30000点经验，8点名誉，30个银币', 31, 110, 10000, 0, 0, FALSE),
  (115, '火种', '蓬莱的火鸟和蜈蚣风筝身上有一种火种，是蓬莱仙灯的主要能量，最近火种很缺少，请你帮忙去寻找30只火种。', '天兵沙空', '天都', '28000点经验，8点名誉，30个银币', 33, 110, 10000, 3654, 30, FALSE),
  (116, '天火燃烧', '女娲补天的时候，然烧的天火余烬落在蓬莱，就是现在的火精灵。扑灭60个火精灵，蓬莱的植物将会更加茂盛。', '天兵扬海', '天都', '40000点经验，10点名誉，35个银币', 35, 110, 10000, 0, 0, FALSE),
  (117, '天判', '瑶池台附近挑战天判官36只，只有强者才能在蓬莱立足。', '天兵沙空', '天都', '43000点经验，12点名誉，80个银币', 37, 110, 10000, 0, 0, FALSE),
  (118, '水母', '前些天，仙女青鸾经过千年之镜附近时，被水母球喷出的毒液弄伤了，请你到千年之镜附近驱杀水母球50只。', '天兵扬海', '天都', '45000点经验，12点名誉，41个银币', 39, 110, 10000, 0, 0, FALSE),
  (12, '减肥的舞姬', '帮龙城舞姬月影收集采集20片减肥食品－－桃叶。', '舞姬月影', '龙城', '精钢手套；4000点经验值；3点名誉值；7银币；蜡烛 1支。', 12, 20, 10000, 4150, 20, FALSE),
  (125, '神秘之石', '客栈老板要求收集“四块神秘之石”交给出云城东北的天照大师。分别到飞空艇仙子、武器师匠、道具师匠、防具师匠处拿到一块神秘之石。', '客栈老板泯仙子', '出云城', '5银币500铜币。', 26, 110, 10000, 3555, 1, FALSE),
  (126, '天命石', '九天玄女要求收集“四块天命石碎片”交给天都东北的天宫帝姬。分别到飞空艇仙子、武器天将、道具天将、防具天将处拿到一块天命石残片。', '九天玄女', '天都', '6银币。', 34, 110, 10000, 3559, 1, FALSE),
  (127, '沙之石', '监城官哈亚图要求收集“四个命运沙漏”交给可以保护沙之石的人，分别到飞空艇仙子、武器师匠、道具师匠、防具师匠处拿到一个命运沙漏，并从与他们的对话中得知关于神庙长老摩迦的事情，于是将命运沙漏带到摩迦那里……', '哈亚图', '楼兰城', '6银币600铜币。', 45, 110, 10000, 3563, 1, FALSE),
  (128, '命运云石（之一）', '与天照大师谈话，得知云石乃瀛洲岛的命运之石。受命在出云城外找到黄鱼怪、玄武兽、苍狼，并杀死它们获得黄鱼胆、玄武甲、苍狼牙。返回出云将战利品交给天照大师。', '天照大师', '出云城', '1177点经验值；6点名誉值；77银币。', 28, 110, 10000, 3567, 1, FALSE),
  (129, '命运云石（之二）', '与天照大师谈话，领取任务。在碧磷毒蛇、赤焰毒蛇和金鱼怪身上找到碧鳞、赤鳞和金鳞交给天照大师。', '天照大师', '出云城', '1750点经验值；6点名誉值；90银币。', 30, 110, 10000, 3570, 1, FALSE),
  (130, '命运云石（之三）', '与天照大师谈话，领取任务。在被异化的牛头面具、小猪神和飞天猪身上找到异面符、异鼻符和异翅符。', '天照大师', '出云城', '2000点经验值；7点名誉值；99银币。', 32, 110, 10000, 3573, 1, FALSE),
  (131, '命运云石（之四）', '接受天照大师使命，前往天都觐见玉皇大帝，寻求神的帮助。', '天照大师', '出云城', '7点名誉值；100银币。', 36, 110, 10000, 0, 0, FALSE),
  (132, '命运云石（之五）', '天都传来消息，众神已经找到了守护云石的方法，在月圆之夜，用雪女的青丝缠绕住云石，然后将鬼侍之头置于云石之上，一同埋入许愿树下，就可以守护住云石，令其免受魔气的侵扰。找到雪女的青丝和双头鬼侍的头，交给天照大师。', '天照大师', '出云城', '王者之靴一双；2000点经验；8点名誉值；150银币。', 40, 110, 10000, 3576, 1, FALSE),
  (133, '命运天命石（之一）', '与天宫帝姬谈话，领取任务。在天郊附近的仙符、火鸟、风妖精身上，寻找到天命石需要的符印、火印和风印，交给天宫帝姬。', '天宫帝姬', '天都', '1800点经验值；8点名誉值；120银币。', 37, 110, 10000, 3606, 1, FALSE),
  (134, '命运天命石（之二）', '与天宫帝姬谈话，领取任务。在瑶台附近的超级飞天猪、天翼魔、虾米小兵身上，寻找到天命石需要的猪耳、魔牙、虾臂，交给天宫帝姬。', '天宫帝姬', '天都', '2300点经验值；8点名誉值；130银币。', 39, 110, 10000, 3609, 1, FALSE),
  (135, '命运天命石（之三）', '与天宫帝姬谈话，领取任务，寻找水之生命的力量。前往千年之镜，收集水母球的唾液、豚仔的汗液和水兽之泪，交给天宫帝姬。', '天宫帝姬', '天都', '3000点经验值；9点名誉值；180银币。', 41, 110, 10000, 3590, 1, FALSE),
  (136, '命运天命石（之四）', '与天宫帝姬谈话，领取任务。继续寻找水之生命的力量，前往东海挑战大闸蟹、墨鱼仔和虾护卫，获得铁蟹钳、铁爪鞭和铁龙须后，交给天宫帝姬。', '天宫帝姬', '天都', '4000点经验值；9点名誉值；200银币。', 44, 110, 10000, 3593, 1, FALSE),
  (137, '命运天命石（之五）', '与天宫帝姬谈话，领取任务。在东海的人鱼巡逻、人鱼护卫、三头龙身上寻找到人鱼珠、人鱼鳞、龙珠，交给天宫帝姬，以便能对神秘的龙族有更多的了解。', '天宫帝姬', '天都', '6000点经验值；10点名誉值；320银币。', 47, 110, 10000, 3596, 1, FALSE),
  (138, '命运沙之石（之一）', '与神庙长老摩迦对话，领取任务。在楼兰城郊，有一些在夜间会发出光芒的仙人掌小妖和巨食人花，采集它们的仙人刺和食人花瓣，帮助沙之石重现光芒。', '神庙长老摩迦', '楼兰城', '2000点经验值；9点名誉值；65银币。', 45, 110, 10000, 3599, 1, FALSE),
  (139, '命运沙之石（之二）', '与神庙长老摩迦对话，领取任务。沙之石已经开始有了微弱的光芒，可惜还远远不够。也许沙虫的卵和行尸的防腐布会有帮助。', '神庙长老摩迦', '楼兰城', '3000点经验值；10点名誉值；340银币。', 47, 110, 10000, 3601, 1, FALSE),
  (14, '客栈老板的口信', '帮龙城客栈老板卢广带口信给城中的居民。', '客栈老板卢广', '龙城', '每次1铜币。', 8, 30, 10000, 0, 0, TRUE),
  (140, '命运沙之石（之三）', '与神庙长老摩迦对话，领取任务。在蚂蚁沙地的兵蚁和守卫蚁身上寻找蚁须和蚁卵,然后交给神庙长老摩迦。', '神庙长老摩迦', '楼兰城', '3600点经验值；10点名誉值；350银币。', 49, 110, 10000, 3603, 1, FALSE),
  (141, '英雄刑天', '前往黄鹤遗址挑战并打败英雄刑天，使他折服并重新进入永恒的安宁。', '盗墓王疾风', '龙城', '12000点经验值；10点名誉值；800银币；称号“挑战刑天的勇士”。', 26, 40, 10000, 0, 0, FALSE),
  (142, '另类慈悲', '前往华山地宫击败不动明王，阻止他灭世的偏激之心。', '捕头尉兴', '龙城', '20000点经验值；12点名誉值；900银币；称号“震撼明王的巨人”。', 30, 42, 10000, 0, 0, FALSE),
  (143, '面具魔王', '前往函谷岭为民除害，消灭可怕的守护面具王。', '巡卫阿吉', '出云城', '25000点经验值；12点名誉值；600银币；称号“夺面英雄”。', 30, 42, 10000, 0, 0, FALSE),
  (144, '无常之乱', '浪人无名在修罗殿中发现了以黑白无常为首的大量鬼魂，你深入魔地一探究竟。', '浪人无名', '出云城', '40000点经验值；15点名誉值；1金币；称号“无常索命人”。', 38, 50, 10000, 0, 0, FALSE),
  (145, '天判之乱', '水魔珠的魔气已经搅得三界六道一片混乱，前往瑶池台，消灭五十个堕入魔道、为祸仙界、真假难辨的天判官。', '天官尹喜', '天都', '10000点经验值；8点名誉值；74银币；称号“判官索命人”。', 35, 45, 10000, 0, 0, FALSE),
  (146, '超级魔猪', '异化升天的魔王飞天猪变成了更加强大的超级魔王飞天猪，前往瑶池台消灭魔猪。', '二郎神杨戟', '天都', '28000点经验值；12点名誉值；660银币；称号“魔猪克星”。', 36, 48, 10000, 0, 0, FALSE),
  (147, '龙宫新主', '蓬莱岛南部的东海里，出现了一个神秘的新主人——美人鱼王。她美艳若桃李，却又狠毒如蛇蝎，被其迷惑而葬身海底的人不计其数。得到天都河上公的指点，消灭美人鱼王。', '河上公', '天都', '63000点经验值；12点名誉值；1金500银币；称号“东海寻美人”。', 45, 58, 10000, 0, 0, FALSE),
  (148, '宝洞异兽', '从楼兰城掘金者阿克木的口中得知麒麟兽再现人间，于是前往流沙洞一探究竟。', '掘金者阿克木', '楼兰城', '87000点经验值；18点名誉值；1金600银币；称号“流沙麒麟客”。', 50, 60, 10000, 0, 0, FALSE),
  (149, '命运【之一】', '获知楼兰城地下王宫的秘密，潜入王宫消灭死亡之后，使其亡魂得到超度。', '先知风涯', '楼兰城', '120000点经验值；20点名誉值；2金；称号“死亡之后的超度人”。', 55, 65, 10000, 0, 0, FALSE),
  (150, '命运【之二】', '时机已经成熟，再次潜入地下王宫，消灭死亡之王。情的力量能使生者死，能使死者生，也许，情才是命运真正的奥秘所在吧！', '先知风涯', '楼兰城', '150000点经验值；20点名誉值；2金200银币；称号“死亡之王的超度人”。', 55, 65, 10000, 0, 0, FALSE),
  (151, '爆竹迎新春【初一】', '大年初一放爆竹，家家户户喜气洋洋，帮拜年娃娃制作爆竹迎接新春的到来！', '拜年娃娃', '各城', '红包1个（爆竹10个）；经验值；名誉值5点。', 1, 110, 10000, 0, 0, FALSE),
  (152, '魔力春联【初二】', '大年初二贴春联，拜年娃娃的一副魔力春联，被调皮的怪物们扯成了碎片，找回至少99张春联碎片。', '拜年娃娃', '各城', '红包1个（糖果5个；化妆卡一张）；经验值；名誉值5点。', 1, 110, 10000, 3695, 99, FALSE),
  (153, '狗年吉祥【初三】', '大年初三神犬来，帮拜年娃娃找回淘气的哮天宝宝，哮天宝宝乃是二郎神座下的神犬，更是本年度天宫的生肖明星，它祝各位Q哥哥Q姐姐狗年福旺财旺爱情旺！', '拜年娃娃', '各城', '宠物通灵犬旺才；名誉值5点。', 10, 110, 10000, 0, 0, FALSE),
  (154, '饺子香喷喷【初四】', '大年初四吃饺子，为拜年娃娃带来桃源村容大嫂精心烹饪的新年饺子呢。要知道在天上做神仙可是没有饺子吃的哦！', '拜年娃娃', '各城', '红包1个（魔法饺子5个）；经验值；名誉值5点。', 10, 110, 10000, 0, 0, FALSE),
  (155, '财神到【初五】', '大年初五财神到，财神爷的百宝囊没有系紧，红包被怪物们哄抢了去，收集10个财神红包，就可以在拜年娃娃那里兑换到压岁钱啦！', '拜年娃娃', '各城', '财神压岁钱；名誉值5点。', 10, 110, 10000, 3697, 10, FALSE),
  (156, '龙城蟠桃宴【初三】', '大年初六蟠桃宴，帮拜年娃娃送请柬，邀请附近德高望重的老人家到龙城来一起共庆新年。', '拜年娃娃', '各城', '红包1个（5个蟠桃）；名誉值5点。', 10, 110, 10000, 0, 0, FALSE),
  (157, '拜年娃娃的祝福【初七】', '大年初七捉迷藏，在龙城四郊寻找拜年娃娃的八个替身，每个替身娃娃都会对对你送出新春的祝福哦！', '拜年娃娃', '各城', '红包1个（双倍经验卡一张）；名誉值5点。
INSERT INTO "game_tasks" ("id", "name", "descr", "npc", "map", "reward", "level_min", "level_max", "exp", "goal_item", "goal_qty", "repeatable") VALUES
  (232, '天道之神兽', '击败飞升峰顶中的天道之神兽，获得进入下一层天之眼的资格。', '古老的石碑', '飞升之天道', '150000点经验值。', 50, 110, 10000, 0, 0, FALSE),
  (233, '试炼', '为了帮助人类中无畏的勇士激发自身潜能，神决定打开五百年来囚禁妖魔的结界，进入妖魔结界，消灭里面的怪物，完成试炼！', '试炼大仙/试炼小仙', '龙城/出云城/新手村', '经验值。每完成6次任务为一轮，满一轮后会得到额外的犒赏。', 12, 60, 10000, 0, 0, FALSE),
  (234, '挑战魔神塔第一层', '魔神塔第一层挑战任务，挑战魔神塔第一层的妖魔，清除第一层所有怪物。累积奖励进入第二层，奖励额度将会大幅提升，连清九层赢取至高名誉。', '镇塔神牛', '新手村', '胜利后可以将奖励累积到第二层赢取更多奖励，失败没有任何奖励。', 10, 110, 10000, 0, 0, FALSE),
  (235, '挑战魔神塔第二层', '魔神塔第二层挑战任务，挑战魔神塔第二层的妖魔，清除第二层所有怪物。累积奖励进入第三层，奖励额度将会大幅提升，连清九层赢取至高名誉。', '镇塔神牛', '新手村', '胜利后可以将奖励累积到第三层赢取更多奖励，挑战失败只能获得第二层鼓励奖。', 10, 110, 10000, 0, 0, FALSE),
  (236, '挑战魔神塔第三层', '魔神塔第三层挑战任务，挑战魔神塔第三层的妖魔；失败只能获得第三层鼓励奖，胜利后可以累积奖励进入第四层，奖励额度将会大幅提升，连清九层赢取至高名誉。', '镇塔神牛', '新手村', '胜利获得称号：“镇妖守卫”，可以将奖励累积到第四层赢取更多奖励，挑战失败只能获得第三层鼓励奖。', 10, 110, 10000, 0, 0, FALSE),
  (237, '挑战魔神塔第四层', '魔神塔第四层挑战任务，挑战魔神塔第四层的妖魔；失败只能获得第四层鼓励奖，胜利后可以累积奖励进入第五层，奖励额度将会大幅提升，连清九层赢取至高名誉。', '镇塔神牛', '新手村', '胜利后可以将奖励累积到第五层赢取更多奖励，挑战失败只能获得第四层鼓励奖。', 10, 110, 10000, 0, 0, FALSE),
  (238, '挑战魔神塔第五层', '魔神塔第五层挑战任务，挑战魔神塔第五层的妖魔；失败只能获得第五层鼓励奖，胜利后可以累积奖励进入第六层，奖励额度将会大幅提升，连清九层赢取至高名誉。', '镇塔神牛', '新手村', '胜利后可以将奖励累积到第六层赢取更多奖励，挑战失败只能获得第五层鼓励奖。', 10, 110, 10000, 0, 0, FALSE),
  (239, '挑战魔神塔第六层', '魔神塔第六层挑战任务，挑战魔神塔第六层的妖魔；失败只能获得第六层鼓励奖，胜利后可以累积奖励进入第七层，奖励额度将会大幅提升，连清九层赢取至高名誉。', '镇塔神牛', '新手村', '胜利获得称号：“除魔侠客”，可以将奖励累积到第七层赢取更多奖励，挑战失败只能获得第六层鼓励奖。', 10, 110, 10000, 0, 0, FALSE),
  (24, '蜗壳笛', '帮长乐村的小叶收集20个蜗牛壳做蜗壳笛。', '小叶', '长乐村', '一顶铁护头；80点经验值；1点名誉值；850铜币；蜡烛1支。', 1, 10, 10000, 4161, 20, FALSE),
  (240, '挑战魔神塔第七层', '魔神塔第七层挑战任务，挑战魔神塔第七层的妖魔；失败只能获得第七层鼓励奖，胜利后可以累积奖励进入第八层，奖励额度将会大幅提升，连清九层赢取至高名誉。', '镇塔神牛', '新手村', '胜利后可以将奖励累积到第八层赢取更多奖励，挑战失败只能获得第七层鼓励奖。', 10, 110, 10000, 0, 0, FALSE),
  (241, '挑战魔神塔第八层', '魔神塔第八层挑战任务，挑战魔神塔第八层的妖魔；失败只能获得第八层鼓励奖，胜利后可以累积奖励进入第九层，奖励额度将会大幅提升，连清九层赢取至高名誉。', '镇塔神牛', '新手村', '胜利后可以将奖励累积到第九层赢取终极奖励，挑战失败只能获得第八层鼓励奖。', 10, 110, 10000, 0, 0, FALSE),
  (242, '挑战魔神塔第九层', '魔神塔第九层终极挑战任务，挑战魔神塔第九层的妖魔；失败只能获得第九层鼓励奖，胜利后赢取至高名誉。', '镇塔神牛', '新手村', '胜利获得称号：“塔狱霸王”，获得终极奖励，挑战失败只能获得第九层鼓励奖。', 10, 110, 10000, 0, 0, FALSE),
  (243, '端午竹叶', '端午节到了，开心果需要采集竹叶做粽子。', '开心果', '龙城', '获得采竹叶的花洒。', 10, 110, 10000, 0, 0, FALSE),
  (244, '变异腾蛇', '神秘仙人需要腾蛇的魂魄，作为报答他会送你一个神秘礼物哦，想要变得更强？绝对不可以错过。', '神秘仙人', '飞升之天道', '获得转职道具醍醐丸。', 50, 110, 10000, 12042, 1, FALSE),
  (245, '灵光之石', '灵光之石乃是一种受到神光沐浴的天石，只有诚心供奉它的人才能拥有它。传说灵光之石来自天泉，水中万物皆有灵性，供奉所需的5条小鱼和200个银币，得到灵光之石。', '飞升使者', '龙城/无泪城', '灵光之石', 1, 110, 10000, 0, 0, TRUE),
  (246, '幻瞳族人上', '为了揭开曹仙遗书中用古老文字记载的秘密，出发前往寻找幻瞳族人的守护花神，希望能够得到幻瞳族人的消息。', '兔子小白', '幻幽平原三', '1200000经验；20点名誉；750银；花神精灵。', 75, 110, 10000, 12095, 1, FALSE),
  (247, '幻瞳族人中', '好不容易找到的守护花神竟然是在沉睡中，去收集材料配出最芬芳的香料，唤醒花神吧。', '神坛祭司风史', '心岛', '1200000经验；20点名誉；750银。', 75, 110, 10000, 12098, 20, FALSE),
  (248, '幻瞳族人下', '花神原神返回人间，但是非常虚弱需要修养，帮助花神收回幻幽平原四的祭坛。', '神坛祭司风史', '心岛', '1200000经验；20点名誉；800银。', 75, 110, 10000, 0, 0, FALSE),
  (249, '拯救红苓', '乌老翁的女儿红苓在野外采药时失踪了，击败妖化腾蛇，救回红苓。', '乌老翁', '无泪城', '1500000点经验值；25点名誉；1个金；一个极品七星石。', 75, 110, 10000, 0, 0, FALSE),
  (25, '拓老爹的竹篓', '帮长乐村的拓老爹编织新的竹篓。', '纪宓', '长乐村', '布手套一双；300点经验值；1点名誉值；1银币500铜币；蜡烛1支。', 1, 10, 10000, 4142, 10, FALSE),
  (250, '湛蓝的眼睛', '乌老翁的确就是幻瞳族人的后裔，可惜失去了宝贵的湛蓝的眼睛。只有找回湛蓝的眼睛才能恢复他幻瞳族人的力量', '乌老翁', '无泪城', '1400000经验；20点名誉；800银。', 75, 110, 10000, 12097, 1, FALSE),
  (251, '幻想开心辞典', '学习之风跨越了边界，幻想开心辞典周末活动再次绚丽登场。', '主持人王小丫', '龙城', '周末活动，许多惊喜大奖等你拿！', 12, 110, 10000, 0, 0, FALSE),
  (252, '幻想开心辞典', '学习之风跨越了边界，幻想开心辞典周末活动再次绚丽登场。', '主持人王小丫', '龙城', '周末活动，许多惊喜大奖等你拿！', 12, 110, 10000, 0, 0, FALSE),
  (253, '雪莲花', '扁鸦需要10朵雪莲花作药引，冰河谷里面应该有他需要的东西', '扁鸦', '无泪城', '经验值800000；金钱200银', 63, 110, 20000, 26061, 10, FALSE),
  (254, '昏头的药师', '冰河谷里面的昏头的药师是无泪城药师的弟弟，药师想从他弟弟身上找点东西回来，你去帮个忙吧。', '药师', '无泪城', '经验值1000000和金钱200银；名誉10点', 63, 110, 20000, 25150, 12, FALSE),
  (255, '百里杜鹃一', '帮助座山雕消灭百里杜鹃里面的蜂王，杀死所有的蜜蜂就会将蜂王召唤出', '座山雕', '无泪城', '经验值1800000；25点名誉；1个金', 69, 110, 20000, 0, 0, FALSE),
  (256, '百里杜鹃二', '热合买提是在世很害怕沙王，进入周庄梦蝶处消灭它。', '热合买提', '落日沙丘西', '经验值2400000；50点名誉；1个金', 69, 110, 20000, 0, 0, FALSE),
  (257, '百里杜鹃三', '沙王被消灭了，风后又来了。一个都不要放过它！', '热合买提', '落日沙丘西', '经验值3600000；10点名誉；200个银', 69, 110, 20000, 0, 0, FALSE),
  (258, '梁祝传奇', '美丽的梁祝传说总是感动人心，进入蝶恋谷带回美丽传说。', '楚乐天', '无泪城', '经验值2400000；15点名誉；500个银，称号“蝶恋之梦”', 69, 110, 20000, 26055, 1, FALSE),
  (259, '天杀的歹徒', '谭香雪的哥哥谭风月在拼命的寻找他的妹妹，没想到妹妹居然命丧黄泉，满足他的愿望，建造一个冰棺吧。', '谭风月', '无泪城', '经验值1000000和金钱200银，名誉10点', 63, 110, 20000, 0, 0, FALSE),
  (26, '收购猴皮', '帮长乐村的柳归舜收集制作神鼓的猴皮。', '柳归舜', '长乐村', '银边猴皮每张180铜币；金边猴皮每张280铜币。', 8, 20, 10000, 3621, 0, TRUE),
  (260, '某些男女', '消失的土地庙中总有些奇怪的事情，教训一下雷鸣走石和百花妖精吧。', '花为媒', '无泪城', '经验值800000；10点名誉；200个银', 69, 110, 20000, 0, 0, FALSE),
  (261, '闹翻天', '帮热合买提传个话给座山雕，解决他们俩的误会', '热合买提', '落日沙丘西', '获得经验值600000；200个银', 69, 110, 20000, 0, 0, FALSE),
  (262, '冰雪之梦', '根据无泪公的描述，进入雪窟地狱，打破谭香雪，才能解脱那里的痛苦。', '无泪公', '无泪城', '经验值3600000；名誉25点；金钱1金', 63, 110, 20000, 26059, 1, FALSE),
  (27, '送信任务', '帮桃源村王子乔送信给龙城客栈老板卢广。', '王子乔', '桃源村', '600点经验值；2点名誉值；1铜币；蜡烛1支。', 10, 20, 10000, 0, 0, FALSE),
  (28, '送信任务', '帮桃源村王子乔送信给龙城捕头尉兴。', '王子乔', '桃源村', '600点经验值；2点名誉值；1铜币；蜡烛1支。', 10, 20, 10000, 0, 0, FALSE),
  (29, '送信任务', '帮桃源村王子乔送信给长乐村的柳归舜。', '王子乔', '桃源村', '1000点经验值；2点名誉值；1200铜币；蜡烛1支。', 10, 20, 10000, 0, 0, FALSE),
  (3, '守卫的委托：消灭大蜗牛怪', '接受龙城守城卫兵阿蒙的委托，去一叶岭或者寻仙道消灭大蜗牛怪，取回10个大蜗牛壳。', '守城卫兵阿蒙', '龙城', '10银币。', 21, 26, 10000, 4347, 10, TRUE),
  (300, '仙人锦囊', '在一片宁静祥和的幻想世界背后，新的危机正在慢慢酝酿，作为被盘古大神所选中的人，你的使命将艰巨而荣耀。接引仙子送给了你三个锦囊，在10级、20级、30级的时候打开，得到神的慷慨馈赠。', '接引仙子', '幻想小岛', '第一个锦囊：加工3的12级职业武器一把，30银币。
INSERT INTO "game_tasks" ("id", "name", "descr", "npc", "map", "reward", "level_min", "level_max", "exp", "goal_item", "goal_qty", "repeatable") VALUES
  (409, '三根茱萸', '机缘成熟后，用三根茱萸唤醒了通玄先生的前世之魂－－铁拐大仙，铁拐大仙将自己的全部灵力注入一张灵符之中，希望你能收集齐另外四张灵符，将它们交给通天塔里的老君使者，他会告诉你许多曾经发生和即将发生的秘密！', '蓟子训', '龙城', '药师冠一顶；6000点经验值；5点名誉值；20银币；灵符一个；称号“济世仁者心”。', 25, 110, 10000, 3474, 3, FALSE),
  (41, '巡城二', '城主悬赏的巡城任务二，收集桃叶，据守城卫兵阿卡透露，完成3个巡城任务会有仙人留下的奖励，还有城主夫人的八卦消息。', '守城卫兵阿卡', '龙城', '3200点经验；2点名誉值；4个银币。
