  (539, '太极杀怪(太极重复)', '赶紧去天都杀20只仙符回来。', '太极循环任务和名誉', '龙城', '太极循环任务，奖励蟠桃1个。连续任务达到第10次轮回太极任务，100%获得太极技能宝石（绑定）1个，25点名誉。放弃任务，连续次数', 90, 150, 32000, 0, 0, FALSE),
  (54, '饥饿的狼群', '继续剿怪之旅，前往华山脚和千叶森林，消灭附近的山狼和灰狼。', '小徒清心', '龙城', '6000点经验；4点名誉值；8个银币。', 19, 110, 10000, 0, 0, FALSE),
  (540, '太极杀怪(太极重复)', '赶紧去楼兰城外杀20只巨型蜗牛怪回来。', '太极循环任务和名誉', '龙城', '太极循环任务，奖励蟠桃1个。连续任务达到第10次轮回太极任务，100%获得太极技能宝石（绑定）1个，25点名誉。放弃任务，连续次数', 90, 150, 32000, 0, 0, FALSE),
  (541, '太极杀怪(太极重复)', '赶紧去楼兰城外杀20只沙漠幻蝶回来。', '太极循环任务和名誉', '龙城', '太极循环任务，奖励蟠桃1个。连续任务达到第10次轮回太极任务，100%获得太极技能宝石（绑定）1个，25点名誉。放弃任务，连续次数', 90, 150, 32000, 0, 0, FALSE),
  (542, '太极杀怪(太极重复)', '赶紧去杀20只紫冥蝎回来。', '太极循环任务和名誉', '龙城', '太极循环任务，奖励蟠桃1个。连续任务达到第10次轮回太极任务，100%获得太极技能宝石（绑定）1个，25点名誉。放弃任务，连续次数', 90, 150, 32000, 0, 0, FALSE),
  (543, '太极杀怪(太极重复)', '赶紧去龙城南郊杀20只树妖回来。', '太极循环任务和名誉', '龙城', '太极循环任务，奖励蟠桃1个。连续任务达到第10次轮回太极任务，100%获得太极技能宝石（绑定）1个，25点名誉。放弃任务，连续次数', 90, 150, 32000, 0, 0, FALSE),
  (544, '太极杀怪(太极重复)', '赶紧去出云外面杀20只苍狼皇回来。', '太极循环任务和名誉', '龙城', '太极循环任务，奖励蟠桃1个。连续任务达到第10次轮回太极任务，100%获得太极技能宝石（绑定）1个，25点名誉。放弃任务，连续次数', 90, 150, 32000, 0, 0, FALSE),
  (545, '太极杀怪(太极重复)', '赶紧去天都杀20只蜈蚣风筝回来。', '太极循环任务和名誉', '龙城', '太极循环任务，奖励蟠桃1个。连续任务达到第10次轮回太极任务，100%获得太极技能宝石（绑定）1个，25点名誉。放弃任务，连续次数', 90, 150, 32000, 0, 0, FALSE),
  (546, '太极之中', '交给我5颗太极技能宝石', '太极循环任务和名誉', '龙城', '飞升后90级玩家可获得技能点1点；6点名誉值。', 90, 150, 32000, 27432, 5, FALSE),
  (547, '斩魂任务', '每天进入妖魔道的时候可以领取斩魂任务，完成可以获得战魂点数。', '飞前传送使者', '楼兰', '随机获得500银至1金500银之间，10点斩魂点数。', 35, 60, 32000, 0, 0, FALSE),
  (548, '斩魂任务', '每天进入妖魔道的时候可以领取斩魂任务，完成可以获得战魂点数。', '飞后传送使者', '楼兰', '随机获得500银至1金500银之间，10点斩魂点数。', 60, 150, 32000, 0, 0, FALSE),
  (549, '进入冲锋战场', '成功进入冲锋战场', '冲锋争霸赛管理员', '雪顶城', '无', 60, 100, 32000, 0, 0, FALSE),
  (55, '爆走机关兽', '接受新的挑战！前往黄鹤遗址，收集破损的木箱锁，并且受命清除轮面怪。', '小徒清心', '龙城', '15000点经验；5点名誉值；10个银币。', 21, 110, 10000, 3648, 20, FALSE),
  (56, '铁钳黑蜂', '再闯黄鹤遗址，清除里面的铁钳人。同时还要消灭千叶森林的黑蜂，又是一次艰巨的任务呢！', '小徒清心', '龙城', '18000点经验；5点名誉值；10个银币。', 23, 110, 10000, 0, 0, FALSE),
  (57, '初探源源洞', '龙城小徒明月派你探察源源洞，这次要挑战的怪物是尖嘴鼠和小虱子。', '小徒明月', '龙城', '8000点经验；4点名誉值；12个银币。', 15, 110, 10000, 0, 0, FALSE),
  (58, '灵蛇蜒', '到达黄鹤遗址消灭30个傀儡怪。再到华山脚或仙踪森林附近收集30个灵蛇蜒。', '小徒明月', '龙城', '8000点经验；5点名誉值；13个银币。', 20, 110, 10000, 3649, 30, FALSE),
  (59, '飞天猴翅', '收集千叶森林里飞天小猴身上掉落的飞猴翅20个。', '小徒明月', '龙城', '10000点经验；5点名誉值；13个银币。', 22, 110, 10000, 3650, 20, FALSE),
  (6, '虎神之皮', '龙城富商藤老爷悬赏30个银币寻找虎神之皮，在华山南麓和华山北麓勇斗虎神，得到宝皮，交与富商藤老爷得到赏金。', '富商藤老爷', '龙城', '30银币；5点名誉值；蜡烛1支；称号“虎神之猎手”。', 22, 32, 10000, 3405, 1, FALSE),
  (60, '清扫地宫', '帮小徒明月到华山地宫和黄鹤遗址清除机关器、烛台怪、齿轮机关人和地翼魔各10只。', '小徒明月', '龙城', '18000点经验；7点名誉值；30个银币。', 24, 110, 10000, 0, 0, FALSE),
  (61, '地翼魔独角兽', '到黄鹤遗址打败20只地翼魔；到华山地宫打败20只独角兽，证明自己的能力。', '小徒明月', '龙城', '25000点经验；12点名誉值；30个银币。称号“龙城巡查使”。', 26, 110, 10000, 0, 0, FALSE),
  (62, '故事吉', '到出云城外打黄鱼怪和蓝鱼怪各30个，回来找阿歧老爹。', '阿歧老爹', '出云城', '12000点经验；7点名誉值；18个银币。', 23, 110, 10000, 0, 0, FALSE),
  (63, '沧海泪', '到出云山道打20只玄武兽，再去大秦山原打30只苍狼，回来找阿歧老爹听故事。', '阿歧老爹', '出云城', '20000点经验；7点名誉值；21个银币。', 25, 110, 10000, 0, 0, FALSE),
  (64, '水漫出云', '幻萤谷中盘踞着很多碧磷毒蛇和赤焰毒蛇，奉阿歧老爹之命驱赶这些毒蛇各30条。', '阿歧老爹', '出云城', '22000点经验；8点名誉值；24个银币。', 27, 110, 10000, 0, 0, FALSE),
  (65, '三仙香', '去大秦山原杀20只苍狼皇，再去收集大熊身上掉落的熊掌10只。', '阿歧老爹', '出云城', '25000点经验；8点名誉值；27个银币。', 29, 110, 10000, 4153, 10, FALSE),
  (66, '指引仙子天心任务', '去找飞空艇仙子云淇请她帮忙。', '指引仙子天心', '桃源村', '200铜币。', 1, 10, 10000, 0, 0, FALSE),
  (67, '指引仙子天晴任务', '帮指引仙子天晴带话给治疗NPC妙仙子。', '指引仙子天晴', '桃源村', '1点名誉值；50铜币。', 1, 10, 10000, 0, 0, FALSE),
  (68, '指引仙子天衣任务', '尝试与人组队，成功后回去找指引仙子天衣。', '指引仙子天衣', '桃源村', '20点经验值。', 1, 10, 10000, 0, 0, FALSE),
  (69, '指引仙子天衣任务', '帮指引仙子天衣带话给桃树仙。', '指引仙子天衣', '桃源村', '馒头2个。', 1, 10, 10000, 0, 0, FALSE),
  (7, '矿源之图', '帮龙城矿工沙良寻找和修补遗失在黄鹤遗址中的矿源之图。', '矿工沙良', '龙城', '白金护腕一对；20000点经验值；5点名誉值；25个银币；蜡烛1支。', 20, 30, 10000, 3407, 5, FALSE),
