  (75, '指引仙子柳溪任务', '帮指引仙子柳溪带话给柳树仙。', '指引仙子柳溪', '长乐村', '馒头2个。', 1, 10, 10000, 0, 0, FALSE),
  (76, '指引仙子柳丝任务', '帮指引仙子柳丝买一瓶豆奶。', '指引仙子柳丝', '长乐村', '200铜币。', 1, 10, 10000, 0, 0, FALSE),
  (77, '指引仙子柳丝任务', '帮指引仙子柳丝带话给仓库管理员天晴。', '指引仙子柳丝', '长乐村', '营养快线一瓶。', 1, 10, 10000, 0, 0, FALSE),
  (78, '老婆大人【之二】', '帮龙城守城卫兵阿炎准备送给老婆大人的生日礼物－－玛瑙戒指。', '守城卫兵阿炎', '龙城', '一双荣誉之靴、45000点经验值； 7点名誉值；25个银币；蜡烛1支。', 25, 40, 10000, 3414, 1, FALSE),
  (79, '小松的心意', '帮桃源村的小松收集10片初生的桃叶，将编好的花篮送给姐姐伊源。', '小松', '桃源村', '长筒鞋一双；500点经验值；2点名誉值；2银币；蜡烛1支。', 5, 12, 10000, 4364, 10, FALSE),
  (8, '珐琅花瓶', '帮龙城客栈老板卢广修补破裂的珐琅花瓶。', '客栈老板卢广', '龙城', '一条琥珀项链；44000点经验值；6点名誉值；25银币；蜡烛1支。', 20, 35, 10000, 4305, 9, FALSE),
  (80, '情人的丝帕', '在30分钟的时限内，乘坐小火鸟，帮桃源村的伊源和长乐村的药衡互赠定情信物——丝帕和白雪珍珠羹。', '伊源', '桃源村', '1个捕兽夹；1000经验值；2点名誉值；5银币；蜡烛1支。', 6, 15, 10000, 0, 0, FALSE),
  (81, '茶姥的药膏', '长乐村拓老爹的风寒病又犯了，请你帮忙去找村里的茶姥要一副药膏。', '拓老爹', '长乐村', '长筒鞋一双；500点经验值；2点名誉值；2银币；蜡烛1支。', 5, 12, 10000, 3623, 10, FALSE),
  (82, '小米的问题', '接受龙城小米的考验，回答他的问题。', '小米', '龙城', '4银币；860点经验值；3支小瓶法力药水。', 15, 25, 10000, 0, 0, FALSE),
  (83, '炼丹的灵药', '帮广成子收集炼制丹药所需的材料：山鼠尾巴、黑蜂翅膀和狼皮。', '广成子', '龙城', '每个山鼠尾巴650铜币；每个黑蜂翅膀600铜币；每张狼皮600铜币。', 25, 31, 10000, 4304, 0, TRUE),
  (84, '草药偏方', '村里壶公的孙子被村外的小黑狗咬伤了，收集药草并尝试合成，将合成好的哈氏金创药交给壶公。', '哈大娘', '桃源村', '布手套一双；230点经验值；1点名誉值；1银币200铜币；蜡烛1支。', 1, 10, 10000, 0, 0, FALSE),
  (85, '小试身手', '小试身手，连续打败5只粉粉兔，通过第一个考验，在指引仙子天晴处学会新手技能。', '容大胖子', '桃源村', '10级以下玩家：新手技能；10级以上玩家：400铜币。', 1, 10, 10000, 0, 0, FALSE),
  (86, '武器师匠的理想', '收集野猪牙，帮助桃源村的武器师匠哈骏完成加工武器的理想。', '武器师匠哈骏', '桃源村', '战士：加工到3级的幻念之枪；
